if ($path === '/admin/login') {
    if ($method === 'POST') {
        $email=(string)($_POST['email']??''); $password=(string)($_POST['password']??'');
        if (hash_equals((string)envv('ADMIN_EMAIL',''),$email) && password_verify($password,(string)envv('ADMIN_PASSWORD_HASH',''))) { session_regenerate_id(true); $_SESSION['admin_authenticated']=true; header('Location: /admin'); exit; }
        $error='Credenciais inválidas';
    }
    ?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Entrar | Checkout 360BH</title><link rel="stylesheet" href="/assets/admin.css"></head><body class="login-page"><main class="login-card"><div class="brand">360BH <small>Checkout financeiro</small></div><h1>Acesso administrativo</h1><p class="muted">Gerencie cobranças e links de pagamento.</p><?php if(!empty($error)): ?><div class="error"><?=htmlspecialchars($error)?></div><?php endif; ?><form method="post"><div class="field"><label for="email">E-mail</label><input id="email" name="email" type="email" autocomplete="username" required></div><div class="field"><label for="password">Senha</label><input id="password" name="password" type="password" autocomplete="current-password" required></div><button class="btn" type="submit">Entrar no painel</button></form></main></body></html><?php exit;
