    if ($method === 'POST') { csrf_check(); $raw=public_token(); db()->prepare('INSERT INTO payment_links(token_hash,amount_cents,currency,description,payment_type,expires_at,max_uses,created_by) VALUES(?,?,?,?,?,?,?,?)')->execute([token_hash($raw),(int)$_POST['amount_cents'],'BRL',$_POST['description'],$_POST['payment_type'],$_POST['expires_at']?:null,(int)$_POST['max_uses']?:1,envv('ADMIN_EMAIL')]); $url=rtrim((string)envv('APP_URL'),' /').'/pagar/'.$raw; }
    if (isset($url)) { ?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Link criado | Checkout 360BH</title><link rel="stylesheet" href="/assets/admin.css"></head><body><div class="admin-shell"><aside class="sidebar"><div class="brand">360BH <small>Checkout financeiro</small></div><nav class="nav"><a href="/admin">&#9632; Visão geral</a><a class="active" href="/admin/links/new">&#43; Criar cobrança</a></nav></aside><section class="main"><header class="topbar"><h1>Link criado</h1></header><main class="content"><div class="panel"><div class="notice">O link foi criado e já pode ser enviado ao cliente.</div><p><strong><?=htmlspecialchars($url)?></strong></p><div class="form-actions"><a class="btn" href="<?=htmlspecialchars($url)?>" target="_blank">Abrir checkout</a><a class="btn btn-light" href="/admin">Voltar ao painel</a></div></div></main></section></div></body></html><?php exit; }
    ?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nova cobrança | Checkout 360BH</title><link rel="stylesheet" href="/assets/admin.css"></head><body><div class="admin-shell"><aside class="sidebar" id="sidebar"><div class="brand">360BH <small>Checkout financeiro</small></div><nav class="nav"><a href="/admin">&#9632; Visão geral</a><a class="active" href="/admin/links/new">&#43; Criar cobrança</a></nav><div class="sidebar-footer"><a href="/admin/logout">Sair da conta</a></div></aside><section class="main"><header class="topbar"><button class="menu-toggle" onclick="document.getElementById('sidebar').classList.toggle('open')" aria-label="Abrir menu">&#9776;</button><h1>Nova cobrança</h1></header><main class="content"><div class="welcome"><h2>Criar link de pagamento</h2><p class="muted">Envie uma cobrança segura sem expor dados do gateway.</p></div><section class="panel"><form method="post"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><div class="form-grid"><div class="field full"><label for="description">Descrição da cobrança</label><input id="description" name="description" placeholder="Ex.: Plano mensal Mapa Glico" required></div><div class="field"><label for="amount">Valor em centavos</label><input id="amount" name="amount_cents" type="number" min="1" step="1" placeholder="Ex.: 9900" required></div><div class="field"><label for="type">Tipo de cobrança</label><select id="type" name="payment_type"><option value="ONE_TIME">Pagamento avulso</option><option value="SUBSCRIPTION">Assinatura mensal</option></select></div><div class="field"><label for="expires">Expiração (opcional)</label><input id="expires" name="expires_at" type="datetime-local"></div><div class="field"><label for="uses">Limite de utilizações</label><input id="uses" name="max_uses" type="number" min="1" value="1"></div></div><div class="form-actions"><button class="btn" type="submit">Gerar link de pagamento</button><a class="btn btn-light" href="/admin">Cancelar</a></div></form></section></main></section></div></body></html><?php exit;
