if ($path === '/admin') { $pdo=db(); $links=$pdo->query('SELECT id,description,amount_cents,payment_type,status,created_at FROM payment_links ORDER BY id DESC LIMIT 50')->fetchAll(); $totalLinks=(int)$pdo->query('SELECT COUNT(*) FROM payment_links')->fetchColumn(); $activeLinks=(int)$pdo->query("SELECT COUNT(*) FROM payment_links WHERE status='ACTIVE'")->fetchColumn(); $paid=(int)$pdo->query("SELECT COUNT(*) FROM payment_intents WHERE status='PAID'")->fetchColumn(); ?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Painel | Checkout 360BH</title><link rel="stylesheet" href="/assets/admin.css"></head><body><div class="admin-shell"><aside class="sidebar" id="sidebar"><div class="brand">360BH <small>Checkout financeiro</small></div><nav class="nav"><a class="active" href="/admin">&#9632; Visão geral</a><a href="/admin/links/new">&#43; Criar cobrança</a><a href="/admin">&#9776; Todas as cobranças</a></nav><div class="sidebar-footer"><a href="/admin/logout">Sair da conta</a></div></aside><section class="main"><header class="topbar"><button class="menu-toggle" onclick="document.getElementById('sidebar').classList.toggle('open')" aria-label="Abrir menu">&#9776;</button><h1>Visão geral</h1><a class="btn btn-light" href="/admin/links/new">Novo link</a></header><main class="content"><div class="welcome"><h2>Olá, administrador</h2><p class="muted">Acompanhe seus links e cobranças em um só lugar.</p></div><section class="cards"><div class="card"><div class="card-label">Links criados</div><div class="card-value"><?=$totalLinks?></div></div><div class="card"><div class="card-label">Links ativos</div><div class="card-value"><?=$activeLinks?></div></div><div class="card"><div class="card-label">Pagamentos aprovados</div><div class="card-value"><?=$paid?></div></div><div class="card"><div class="card-label">Gateway</div><div class="card-value" style="font-size:20px">Asaas</div></div></section><section class="panel"><div class="panel-header"><h2>Links de cobrança recentes</h2><a class="btn" href="/admin/links/new">Criar link</a></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Descrição</th><th>Valor</th><th>Tipo</th><th>Status</th><th>Criado em</th></tr></thead><tbody><?php if(!$links): ?><tr><td colspan="6" class="muted">Nenhum link criado ainda.</td></tr><?php else: foreach($links as $l): ?><tr><td>#<?=$l['id']?></td><td><?=htmlspecialchars($l['description'])?></td><td>R$ <?=money((int)$l['amount_cents'])?></td><td><?=($l['payment_type']==='SUBSCRIPTION'?'Assinatura':'Avulso')?></td><td><span class="status status-<?=strtolower($l['status'])?>"><?=$l['status']?></span></td><td><?=date('d/m/Y H:i',strtotime($l['created_at']))?></td></tr><?php endforeach; endif; ?></tbody></table></div></section></main></section></div></body></html><?php exit; }
